#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "actor_social_occupancy.hpp"
#include "resident/domains/interaction/interaction_context_codec_fields.hpp"
#include "resident/domains/interaction/interaction_model.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
namespace hanmo::resident {namespace {
template<class A>Status source(A&a,SourceRef&v){a.field("domain",v.domain);a.field("kind",v.kind);return a.field("id",v.id);}
template<class A>Status value(A&a,ActorSocialOccupancy&v){a.optional("interaction_id",v.interaction_id,[](auto&c,auto&x){return c.field("value",x);});return a.optional("party_id",v.party_id,[](auto&c,auto&x){return c.field("value",x);});}
template<class A>Status party_context(A&a,InteractionContext&v){a.field("place_id",v.place_id);a.field("provider_actor_id",v.provider_actor_id);a.field("role_id",v.role_id);a.optional("kind",v.kind,[](auto&c,auto&x){return c.field("value",x);});a.optional("encounter_id",v.encounter_id,[](auto&c,auto&x){return c.field("value",x);});a.optional("input_error",v.input_error,[](auto&c,auto&x){return c.field("value",x);});return dynamic_codec::strings(a,"field_order",v.field_order);}
template<class A>Status party_acceptance(A&a,PartyMembershipAcceptance&v){dynamic_codec::enumeration(a,"kind",v.kind,2);a.field("leader_actor_id",v.leader_actor_id);a.field("role_id",v.role_id);a.field("cost_per_tick",v.cost_per_tick);a.object("context",[&](auto&c){return party_context(c,v.context);});a.optional("authored_node",v.authored_node,[](auto&c,auto&n){c.field("session_actor_id",n.session_actor_id);c.field("session_id",n.session_id);c.field("dialogue_id",n.dialogue_id);c.field("node_id",n.node_id);return c.field("node_kind",n.node_kind);});return a.optional("authored_declaration_id",v.authored_declaration_id,[](auto&c,auto&id){return c.field("value",id);});}
template<class A>Status transition(A&a,ActorSocialOccupancyTransition&v,Integer version){a.field("id",v.id);a.field("actor_id",v.actor_id);a.object("previous_source",[&](auto&c){return source(c,v.previous_source);});a.object("before",[&](auto&c){return value(c,v.before);});a.object("after",[&](auto&c){return value(c,v.after);});a.object("occurred_at",[&](auto&c){return dynamic_codec::exact_moment(c,v.occurred_at);});dynamic_codec::enumeration(a,"cause",v.cause,version==3?14:13);a.field("original_context_id",v.original_context_id);a.field("initiator_actor_id",v.initiator_actor_id);a.optional("actual_cause_source",v.actual_cause_source,[](auto&c,auto&v){return source(c,v);});if(version==1){if(v.party_acceptance||v.session_opening)return a.reject("UnselectedSocialOccupancyEvidence");return a.status();}a.optional("party_acceptance",v.party_acceptance,[](auto&c,auto&v){return party_acceptance(c,v);});if(version==2)return v.session_opening?a.reject("UnselectedInteractionSessionOpening"):a.status();a.optional("session_opening",v.session_opening,[](auto&c,auto&o){c.field("session_id",o.session_id);c.field("actor_id",o.actor_id);c.field("dialogue_id",o.dialogue_id);return c.object("context",[&](auto&n){return interaction_context_codec::fields(n,o.context);});});if(!a.status().ok)return a.status();if(actor_social_occupancy_opening_cause(v.cause)!=bool(v.session_opening))return a.reject("InteractionSessionOpeningEvidenceRequired");return a.status();}
template<class A>Status fields(A&a,ActorSocialOccupancySources&s){a.field("version",s.version);if(!actor_social_occupancy_version(s.version))return a.reject("UnsupportedActorSocialOccupancyVersion");return dynamic_codec::table(a,"transitions",s.transitions,[&](auto&c,auto&v){return transition(c,v,s.version);});}
}
Status visit_actor_social_occupancy_checkpoint(CodecVisitor&a,ActorSocialOccupancySources&s){return fields(a,s);}
Outcome<ActorSocialOccupancySources>decode_actor_social_occupancy(const BoundaryValue&v){ActorSocialOccupancySources s;dynamic_codec::JsonArchive a(v);auto r=fields(a,s);if(r.ok)r=a.finish();return r.ok?Outcome<ActorSocialOccupancySources>{true,std::move(s),{}}:Outcome<ActorSocialOccupancySources>{false,{},r.error};}
Outcome<BoundaryValue>encode_actor_social_occupancy(const ActorSocialOccupancySources&s){return dynamic_projection::encode(s,[](auto&a,auto&v){return fields(a,v);});}
Status emit_actor_social_occupancy_projection(ProjectionWriter&w,std::string_view key,const ActorSocialOccupancySources&s){return dynamic_projection::emit(w,key,s,[](auto&a,auto&v){return fields(a,v);});}
Outcome<bool> emit_actor_social_occupancy_fact_payload_fields(ProjectionWriter&w,const CommonStore&common,const InteractionState&i,const NativeActorSocialOccupancyRead&read,const FactRecord&h){
 if(h.domain!="interaction"||h.kind!="actor_social_occupancy_changed")return {true,false,{}};const auto*actual=common.state().facts.find(h.id);if(!actual||actual->kind!=h.kind||actual->domain!=h.domain||!i.social_occupancy)return {false,false,common_failure("SocialOccupancySourceHeaderMissing",h.id).error};auto moment=read.read_source_moment({h.domain,h.kind,h.id},1);if(!moment.ok)return {false,false,moment.error};const auto*row=i.social_occupancy->transitions.find(h.id);if(!row)return {false,false,common_failure("SocialOccupancyTransitionMissing",h.id).error};dynamic_projection::Archive archive(w);auto status=transition(archive,const_cast<ActorSocialOccupancyTransition&>(*row),i.social_occupancy->version);return status.ok?Outcome<bool>{true,true,{}}:Outcome<bool>{false,false,status.error};
}

}
